        as b("bundleId" text, name text, "bundlePrice" numeric, "thresholdAmount" numeric, items jsonb)
)
insert into bundle (id, name, bundle_price, threshold_amount, activity_id, status)
select "bundleId", name, "bundlePrice", "thresholdAmount", 'activity-board-v2', 'ACTIVE'
from bundles
on conflict (id) do update
set name = excluded.name,
    bundle_price = excluded.bundle_price,
    threshold_amount = excluded.threshold_amount,
    activity_id = excluded.activity_id,
    status = excluded.status,
    updated_at = now();

delete from bundle_item
where bundle_id in ('bundle-abv2-driving-package', 'bundle-abv2-water-drink-package', 'bundle-abv2-long-haul-package');

