insert into coupon_template (
    coupon_template_id, coupon_name, face_value, min_spend_amount, applicable_categories, excluded_categories,
    applicable_product_codes, excluded_product_codes, valid_days, issue_quantity, per_customer_limit,
    redeem_channels, member_only, stackable, discount_rate
)
select 'province-feature-half-2026', '省区特色5折券', 0.00, 15.00, '[]'::jsonb, '["香烟","化肥"]'::jsonb,
       "productCodes", '[]'::jsonb, 60, 1000, 2, '["checkout"]'::jsonb, true, false, 0.5000
from province_scope
union all
select 'province-feature-70-2026', '省区特色7折券', 0.00, 15.00, '[]'::jsonb, '["香烟","化肥"]'::jsonb,
       "productCodes", '[]'::jsonb, 60, 1000, 2, '["checkout"]'::jsonb, true, false, 0.7000
from province_scope
on conflict (coupon_template_id) do update
set coupon_name = excluded.coupon_name,
    face_value = excluded.face_value,
    min_spend_amount = excluded.min_spend_amount,
    applicable_categories = excluded.applicable_categories,
    excluded_categories = excluded.excluded_categories,
    applicable_product_codes = excluded.applicable_product_codes,
    excluded_product_codes = excluded.excluded_product_codes,
    valid_days = excluded.valid_days,
    issue_quantity = excluded.issue_quantity,
    per_customer_limit = excluded.per_customer_limit,
    redeem_channels = excluded.redeem_channels,
    member_only = excluded.member_only,
    stackable = excluded.stackable,
    discount_rate = excluded.discount_rate,
    updated_at = now();

with templates as (
    select * from coupon_template
    where coupon_template_id in ('province-feature-half-2026', 'province-feature-70-2026')
), issued as (
    select 'demo-province-half-001' as couponId, * from templates where coupon_template_id = 'province-feature-half-2026'
    union all
    select 'demo-province-70-001' as couponId, * from templates where coupon_template_id = 'province-feature-70-2026'
)
insert into coupon (
    coupon_id, coupon_template_id, coupon_name, face_value, min_spend_amount, applicable_categories,
    excluded_categories, applicable_product_codes, excluded_product_codes, valid_from, valid_until,
    member_only, stackable, status, issued_at, operator_id, discount_rate
)
select couponId, coupon_template_id, coupon_name, face_value, min_spend_amount, applicable_categories,
       excluded_categories, applicable_product_codes, excluded_product_codes,
       date '2026-07-01', date '2026-12-31', member_only, stackable, 'AVAILABLE', now(),
       'flyway-activity-board-v2', discount_rate
from issued
on conflict (coupon_id) do update
set coupon_template_id = excluded.coupon_template_id,
    coupon_name = excluded.coupon_name,
    face_value = excluded.face_value,
    min_spend_amount = excluded.min_spend_amount,
    applicable_categories = excluded.applicable_categories,
    excluded_categories = excluded.excluded_categories,
    applicable_product_codes = excluded.applicable_product_codes,
    excluded_product_codes = excluded.excluded_product_codes,
    valid_from = excluded.valid_from,
    valid_until = excluded.valid_until,
    member_only = excluded.member_only,
    stackable = excluded.stackable,
    status = excluded.status,
    issued_at = excluded.issued_at,
    operator_id = excluded.operator_id,
    discount_rate = excluded.discount_rate,
