        as r("ruleId" text, "activityName" text, "ruleType" text, priority int, "exclusiveGroup" text, stackable boolean,
             condition jsonb, benefit jsonb, "sourceSheetName" text, "sourceRowNumber" int)
), prepared as (
    select
        'draft-' || "ruleId" || '-abv2' as draftId,
        "ruleId" as ruleId,
        "activityName" as activityName,
        "ruleType" as ruleType,
        "sourceSheetName" as sourceSheetName,
        "sourceRowNumber" as sourceRowNumber,
        condition,
        benefit,
        jsonb_build_object(
            'ruleId', "ruleId",
            'activityName', "activityName",
            'ruleType', "ruleType",
            'priority', priority,
            'exclusiveGroup', "exclusiveGroup",
            'stackable', stackable,
            'status', 'CONFIRMED',
            'condition', condition,
            'benefit', benefit,
            'version', 'activity-board-v2'
        ) as ruleJson
    from activity_rules
)
insert into promotion_rule_draft (
    draft_id, rule_id, source_import_id, source_sheet_name, source_row_number, rule_type, status,
    condition_json, benefit_json, rule_json, manual_locked, created_by
)
select draftId, ruleId, 'activity-board-v2', sourceSheetName, sourceRowNumber, ruleType, 'CONFIRMED',
       condition, benefit, ruleJson, true, 'flyway-activity-board-v2'
from prepared
on conflict (rule_id) do update
set source_import_id = excluded.source_import_id,
    source_sheet_name = excluded.source_sheet_name,
    source_row_number = excluded.source_row_number,
    rule_type = excluded.rule_type,
    status = excluded.status,
    condition_json = excluded.condition_json,
    benefit_json = excluded.benefit_json,
    rule_json = excluded.rule_json,
    manual_locked = excluded.manual_locked,
    updated_at = now();

