        as r("ruleId" text, "activityName" text, "ruleType" text, priority int, "exclusiveGroup" text, stackable boolean,
             condition jsonb, benefit jsonb, "sourceSheetName" text, "sourceRowNumber" int)
), prepared as (
    select
        "ruleId" as ruleId,
        "activityName" as activityName,
        "ruleType" as ruleType,
        "sourceSheetName" as sourceSheetName,
        "sourceRowNumber" as sourceRowNumber,
        jsonb_build_object(
            'ruleId', "ruleId",
            'activityName', "activityName",
            'ruleType', "ruleType",
            'priority', priority,
            'exclusiveGroup', "exclusiveGroup",
            'stackable', stackable,
            'status', 'CONFIRMED',
            'condition', condition,
            'benefit', benefit,
            'version', 'activity-board-v2'
        ) as ruleJson
    from activity_rules
)
insert into promotion_rule_version (
    version_id, rule_id, source_import_id, source_sheet_name, source_row_number, rule_type, status,
    rule_json, created_by, confirmed_at, confirmed_by, change_reason
)
select 'ver-' || ruleId || '-abv2', ruleId, 'activity-board-v2', sourceSheetName, sourceRowNumber, ruleType,
       'CONFIRMED', ruleJson, 'flyway-activity-board-v2', now(), 'flyway-activity-board-v2', 'Activity board structured import v2'
from prepared
on conflict (version_id) do nothing;

insert into promotion_rule_audit_log (
    audit_id, rule_id, action, status_before, status_after, operator_id, change_reason
)
select 'audit-abv2-' || rule_id, rule_id, 'CONFIRMED', null, 'CONFIRMED', 'flyway-activity-board-v2',
       'Activity board structured import v2'
from promotion_rule_draft
where source_import_id = 'activity-board-v2'
on conflict (audit_id) do nothing;
